//! The board: a generated markdown view of the ledger (`.mesh/BOARD.md`).

use std::fmt::Write as _;

use serde::Serialize;

use crate::ledger::{Ledger, NoteKind, Readiness, Task};
use crate::lifecycle::State;
use crate::time::fmt_utc;

/// Longest table cell, in characters.
const MAX_CELL: usize = 120;

/// The first line of the board. It marks the file as generated.
pub const BOARD_HEADER: &str =
    "<!-- Generated by `mesh`. Do not edit. Run `mesh board` to refresh. -->";

/// Board groups, in display order.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum Group {
    /// Submitted, all dependencies completed.
    Ready,
    /// Claimed.
    Working,
    /// Waiting for an answer.
    InputRequired,
    /// Submitted, waiting for dependencies.
    Waiting,
    /// Submitted, a dependency failed or was canceled.
    Blocked,
    /// Failed.
    Failed,
    /// Completed.
    Completed,
    /// Canceled.
    Canceled,
}

impl Group {
    /// All groups, in display order.
    pub const ALL: [Self; 8] = [
        Self::Ready,
        Self::Working,
        Self::InputRequired,
        Self::Waiting,
        Self::Blocked,
        Self::Failed,
        Self::Completed,
        Self::Canceled,
    ];

    /// The display name.
    #[must_use]
    pub const fn title(self) -> &'static str {
        match self {
            Self::Ready => "ready",
            Self::Working => "working",
            Self::InputRequired => "input-required",
            Self::Waiting => "waiting",
            Self::Blocked => "blocked",
            Self::Failed => "failed",
            Self::Completed => "completed",
            Self::Canceled => "canceled",
        }
    }
}

/// The group of a task.
#[must_use]
pub fn group_of(ledger: &Ledger, task: &Task) -> Group {
    match task.life.state() {
        State::Submitted => match ledger.readiness(&task.spec.id) {
            Readiness::Ready => Group::Ready,
            Readiness::Blocked(_) => Group::Blocked,
            Readiness::Waiting(_) | Readiness::NotSubmitted => Group::Waiting,
        },
        State::Working => Group::Working,
        State::InputRequired => Group::InputRequired,
        State::Failed => Group::Failed,
        State::Completed => Group::Completed,
        State::Canceled => Group::Canceled,
    }
}

/// The number of tasks in each group, in display order.
#[must_use]
pub fn counts(ledger: &Ledger) -> Vec<(Group, usize)> {
    Group::ALL
        .iter()
        .map(|g| {
            (
                *g,
                ledger.tasks().filter(|t| group_of(ledger, t) == *g).count(),
            )
        })
        .collect()
}

/// One line of facts about the task, for its group.
#[must_use]
pub fn info(ledger: &Ledger, task: &Task) -> String {
    let ids = |v: &[crate::ids::TaskId]| {
        v.iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>()
            .join(", ")
    };
    let note = |k: NoteKind| task.last_note(k).unwrap_or("").to_string();
    match group_of(ledger, task) {
        Group::Ready | Group::Waiting | Group::Blocked => match ledger.readiness(&task.spec.id) {
            Readiness::Waiting(d) => format!("waits for: {}", ids(&d)),
            Readiness::Blocked(d) => format!("blocked by: {}", ids(&d)),
            _ if task.spec.paths.is_empty() => String::new(),
            _ => format!("paths: {}", task.spec.paths.join(", ")),
        },
        Group::Working => task.life.lease().map_or_else(String::new, |l| {
            format!(
                "{} ({}), token {}, until {}",
                l.agent,
                l.worker,
                l.token,
                fmt_utc(l.expires_at)
            )
        }),
        Group::InputRequired => format!("question: {}", note(NoteKind::Question)),
        Group::Failed => format!(
            "failures {}/{}: {}",
            task.life.failures(),
            task.life.max_failures(),
            task.notes.last().map_or("", |n| n.text.as_str())
        ),
        Group::Completed => note(NoteKind::Evidence),
        Group::Canceled => note(NoteKind::Cancel),
    }
}

/// Makes text safe for one markdown table cell.
fn cell(text: &str) -> String {
    let flat: String = text
        .chars()
        .map(|c| if c.is_control() { ' ' } else { c })
        .collect();
    let mut out: String = flat.trim().chars().take(MAX_CELL).collect();
    if flat.trim().chars().count() > MAX_CELL {
        out.push('…');
    }
    out.replace('|', "\\|")
}

/// Renders the board. The output depends only on the ledger.
#[must_use]
pub fn render(ledger: &Ledger) -> String {
    let mut out = format!("{BOARD_HEADER}\n\n# Mesh board\n\n");
    if ledger.is_empty() {
        out.push_str("No tasks.\n");
        return out;
    }
    let summary: Vec<String> = counts(ledger)
        .iter()
        .map(|(g, n)| format!("{} {n}", g.title()))
        .collect();
    let _ = writeln!(out, "{} tasks: {}.", ledger.len(), summary.join(", "));
    for group in Group::ALL {
        let tasks: Vec<&Task> = ledger
            .tasks()
            .filter(|t| group_of(ledger, t) == group)
            .collect();
        if tasks.is_empty() {
            continue;
        }
        let _ = write!(
            out,
            "\n## {} ({})\n\n| Task | Title | Skill | Info |\n|---|---|---|---|\n",
            group.title(),
            tasks.len()
        );
        for t in tasks {
            let _ = writeln!(
                out,
                "| {} | {} | {} | {} |",
                t.spec.id,
                cell(&t.spec.title),
                t.spec.skill,
                cell(&info(ledger, t))
            );
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::event::TaskSpec;
    use crate::ids::{AgentId, Skill, TaskId};
    use crate::ledger::{Command, Ctx};
    use crate::registry::{Registry, DEFAULT_REGISTRY};

    fn tid(s: &str) -> TaskId {
        TaskId::new(s).unwrap_or_else(|e| panic!("{e}"))
    }

    fn sample() -> Ledger {
        let reg = Registry::parse(DEFAULT_REGISTRY).unwrap_or_else(|e| panic!("{e}"));
        let skill = |s: &str| Skill::new(s).unwrap_or_else(|e| panic!("{e}"));
        let mut build = TaskSpec::new(tid("a"), "Build | the thing", skill("build"));
        build.paths = vec!["src/**".into()];
        let mut review = TaskSpec::new(tid("b"), "Review", skill("review"));
        review.deps = vec![tid("a")];
        let spec = TaskSpec::new(tid("c"), "Spec", skill("spec"));
        let mut ledger = Ledger::new();
        let ctx = Ctx {
            now: 1_700_000_000,
            registry: &reg,
        };
        ledger
            .execute(Command::Plan(vec![build, review, spec]), &ctx)
            .unwrap_or_else(|e| panic!("{e}"));
        ledger
            .execute(
                Command::Claim {
                    task: Some(tid("a")),
                    agent: AgentId::new("builder").unwrap_or_else(|e| panic!("{e}")),
                    worker: None,
                    ttl: 60,
                },
                &ctx,
            )
            .unwrap_or_else(|e| panic!("{e}"));
        ledger
    }

    #[test]
    fn groups_and_counts() {
        let l = sample();
        let g = |id: &str| group_of(&l, l.task(&tid(id)).unwrap_or_else(|| panic!("{id}")));
        assert_eq!(g("a"), Group::Working);
        assert_eq!(g("b"), Group::Waiting);
        assert_eq!(g("c"), Group::Ready);
        let c = counts(&l);
        assert_eq!(c.len(), Group::ALL.len());
        assert_eq!(c.iter().map(|(_, n)| n).sum::<usize>(), 3);
        assert!(c.contains(&(Group::Working, 1)));
    }

    #[test]
    fn render_is_stable_and_escapes_tables() {
        let l = sample();
        let text = render(&l);
        assert_eq!(text, render(&l));
        assert!(text.starts_with(BOARD_HEADER));
        assert!(text.contains("## working (1)"));
        assert!(text.contains("Build \\| the thing"));
        assert!(text.contains("2023-11-14T22:14:20Z"));
        assert!(text.ends_with('\n'));
        let ready = text.find("## ready").unwrap_or(0);
        let working = text.find("## working").unwrap_or(0);
        assert!(ready < working);
    }

    #[test]
    fn empty_board_says_so() {
        assert!(render(&Ledger::new()).contains("No tasks."));
    }
}
